package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.DeriveMetricsVO;

class DeriveMetricsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of derive metrics of observed source")
  void test_derive_metrics_value_holder_assign_plain_value() {
    Object holder = new Object();
    DeriveMetricsValueHolder<Object> value = new DeriveMetricsValueHolder<>(holder);
    Assertions.assertSame(holder, value.deriveMetrics(true), "Setters must return the holder");
    Assertions.assertTrue(value.getDeriveMetricsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getDeriveMetrics().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.deriveMetricsNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDeriveMetricsValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of derive metrics of observed source")
  void test_derive_metrics_value_holder_assign_value_object() {
    Object holder = new Object();
    DeriveMetricsValueHolder<Object> value = new DeriveMetricsValueHolder<>(holder);
    DeriveMetricsVO vo = DeriveMetricsVO.from(true);
    Assertions.assertFalse(value.getDeriveMetricsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.deriveMetrics(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDeriveMetricsValue().orElseThrow());
    Assertions.assertSame(holder, value.deriveMetrics(Optional.empty()));
    Assertions.assertFalse(value.getDeriveMetricsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.deriveMetrics(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDeriveMetricsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of derive metrics of observed source against the original")
  void test_derive_metrics_value_holder_read() {
    Object holder = new Object();
    DeriveMetricsValueHolder<Object> value = new DeriveMetricsValueHolder<>(holder);
    DeriveMetricsVO vo = DeriveMetricsVO.from(true);
    DeriveMetricsVO other = DeriveMetricsVO.from(true);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getDeriveMetricsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDeriveMetrics(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDeriveMetrics(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.deriveMetrics(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDeriveMetrics(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDeriveMetrics(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of derive metrics of observed source")
  void test_derive_metrics_value_holder_unset() {
    Object holder = new Object();
    DeriveMetricsValueHolder<Object> value = new DeriveMetricsValueHolder<>(holder);
    DeriveMetricsVO vo = DeriveMetricsVO.from(true);
    value.deriveMetrics(vo);
    Assertions.assertSame(holder, value.unsetDeriveMetricsIfMatches("deriveMetrics_other"));
    Assertions.assertTrue(value.getDeriveMetricsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDeriveMetricsIfMatches("deriveMetrics"));
    Assertions.assertFalse(value.getDeriveMetricsValue().isPresent(),
        "The field name must clear the value");
    value.deriveMetrics(vo);
    Assertions.assertSame(holder, value.unsetDeriveMetrics());
    Assertions.assertFalse(value.getDeriveMetricsValue().isPresent(), "Unset must clear the value");
  }
}
